<script setup lang="ts">
import type { LobbyRoom, LobbyMatch } from '../../stores/lobby'
import { initial, roomModeText, roomJoinable } from './view'
defineProps<{ room?: LobbyRoom; match?: LobbyMatch }>()
defineEmits<{ (event: 'join', room: LobbyRoom): void; (event: 'watch', match: LobbyMatch): void }>()
</script>
<template>
  <article v-if="room" class="lp-room-card" :data-testid="'lobby-room-' + room.roomId"><div class="lp-card-top"><span class="lp-tag">{{ roomModeText(room) }} · {{ room.public ? '公开' : '私密' }}</span><span class="lp-tag" :class="{ 'lp-tag--good': roomJoinable(room) }">{{ roomJoinable(room) ? '等待对手' : '已满' }}</span></div><h2>{{ room.name }}</h2><p class="lp-help">房号 {{ room.roomId }}</p><div class="lp-duel lp-duel--card"><div><span class="lp-avatar">{{ initial(room.host) }}</span><b>{{ room.host }}</b><small>房主</small></div><span class="lp-vs">VS</span><div><span class="lp-avatar lp-avatar--empty">{{ roomJoinable(room) ? '＋' : '●' }}</span><b>{{ roomJoinable(room) ? '空位' : '已就座' }}</b><small>{{ roomJoinable(room) ? '等待加入' : '等待开局' }}</small></div></div><footer class="lp-card-footer"><span>{{ room.players }} / {{ room.capacity }} 人</span><button class="button lp-primary" :data-testid="'lobby-room-join-' + room.roomId" :disabled="!roomJoinable(room)" @click="$emit('join', room)">{{ roomJoinable(room) ? '加入房间' : '房间已满' }}</button></footer></article>
  <article v-else-if="match" class="lp-room-card" :data-testid="'lobby-match-' + match.roomId"><div class="lp-card-top"><span class="lp-tag" :class="{ 'lp-tag--gold': match.ranked }">{{ match.ranked ? '排位对战' : '休闲对战' }}</span><span class="lp-live">进行中</span></div><div class="lp-duel lp-duel--card"><div><span class="lp-avatar">{{ initial(match.names[0]) }}</span><b>{{ match.names[0] || '玩家' }}</b></div><span class="lp-vs">VS</span><div><span class="lp-avatar lp-avatar--opponent">{{ initial(match.names[1]) }}</span><b>{{ match.names[1] || '玩家' }}</b></div></div><div class="lp-match-progress"><span>当前进度</span><b>第 {{ match.round }} 回合</b></div><footer class="lp-card-footer"><span>{{ match.spectators }} / {{ match.spectatorLimit }} 人观战</span><button class="button" :data-testid="'lobby-match-spectate-' + match.roomId" @click="$emit('watch', match)">进入观战</button></footer></article>
</template>
